css:
.akd-header { border-bottom: 2px solid #2C3E50; padding-bottom: 8px; margin-bottom: 12px; }
.akd-header td { vertical-align: top; }
.akd-company { font-size: 16px; font-weight: 600; color: #2C3E50; }
.akd-trn { font-size: 10px; color: #555; }
.akd-meta th { text-align: left; background: #F4F4F4; padding: 4px 6px; }
.akd-meta td { padding: 4px 6px; }
.akd-items { width: 100%; border-collapse: collapse; margin-top: 12px; }
.akd-items th, .akd-items td { border: 1px solid #DDD; padding: 4px 6px; font-size: 10px; }
.akd-items th { background: #2C3E50; color: white; }
.akd-totals { margin-top: 8px; float: right; min-width: 280px; }
.akd-totals td { padding: 3px 6px; }
.akd-totals .total-row { font-weight: 600; border-top: 2px solid #2C3E50; }
.akd-terms { margin-top: 20px; font-size: 9px; color: #444; }
.akd-bank { margin-top: 12px; font-size: 9px; padding: 6px; background: #F9F9F9; border: 1px dashed #CCC; }
.akd-footer { margin-top: 24px; padding-top: 8px; border-top: 1px solid #DDD; font-size: 8px; text-align: center; color: #888; }
